package nl.smartstreamlabs.sbwdroneconfig;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import net.minecraft.nbt.*;import net.minecraft.world.phys.Vec3;
public class Sk01DataTest {
 private static Sk01Entry entry(int i){return new Sk01Entry(new UUID(0,i),new UUID(1,i),i*17d,64,i*-17d,90,1,"sbwdroneconfig:sk01",100+i,true);}
 private static CompoundTag save(Sk01Data d)throws Exception{var method=Arrays.stream(Sk01Data.class.getDeclaredMethods()).filter(m->m.getName().equals("save")&&m.getReturnType()==CompoundTag.class).findFirst().orElseThrow();return(CompoundTag)(method.getParameterCount()==1?method.invoke(d,new CompoundTag()):method.invoke(d,new CompoundTag(),null));}
 private static Sk01Data load(CompoundTag n)throws Exception{var method=Arrays.stream(Sk01Data.class.getDeclaredMethods()).filter(m->m.getName().equals("load")).findFirst().orElseThrow();method.setAccessible(true);return(Sk01Data)(method.getParameterCount()==1?method.invoke(null,n):method.invoke(null,n,null));}
 @Test void compactVersionedThousandRecordRoundtrip()throws Exception{var d=new Sk01Data();for(int i=0;i<1000;i++)d.put(entry(i));var n=save(d);assertEquals(1,n.getInt("Version"));var restored=load(n);assertEquals(d.entries,restored.entries);assertEquals(1000,restored.entries.size());assertFalse(n.toString().contains("Inventory"));}
 @Test void updatesMoveChunkIndexWithoutDuplication(){var d=new Sk01Data();var e=entry(1);d.put(e);var next=e.settled(new Vec3(-33,63.5,65));d.put(next);assertTrue(d.chunk(e.chunk()).isEmpty());assertEquals(next,d.chunk(next.chunk()).get(e.id()));assertEquals(1,d.entries.size());assertFalse(next.pending());assertEquals(e.source(),next.source());}
 @Test void doubleCleanupIsIdempotent(){var d=new Sk01Data();var e=entry(2);d.put(e);assertEquals(e,d.remove(e.id()));assertNull(d.remove(e.id()));assertTrue(d.entries.isEmpty());assertTrue(d.chunks.isEmpty());}
 @Test void sameIdCannotDuplicateOnLoad()throws Exception{var d=new Sk01Data();var e=entry(3);d.put(e);var n=save(d);n.getList("Remains",Tag.TAG_COMPOUND).add(n.getList("Remains",Tag.TAG_COMPOUND).get(0).copy());assertEquals(1,load(n).entries.size());}
 @Test void rendererLimitsCannotAffectStorage(){var d=new Sk01Data();for(int i=0;i<1000;i++)d.put(entry(i));for(int i=0;i<20;i++)assertEquals(1000,d.entries.size());assertEquals(1000,d.chunks.values().stream().mapToInt(Map::size).sum());}
 @Test void humanBoundsAreFlatAndRotate(){var e=entry(4).settled(Vec3.ZERO);var box=e.bounds();assertEquals(.436,box.getYsize(),.00001);assertEquals(1.902,box.getXsize(),.00001);assertEquals(1.012,box.getZsize(),.00001);}
 @Test void invalidGeometryRejected(){assertThrows(IllegalArgumentException.class,()->new Sk01Entry(UUID.randomUUID(),UUID.randomUUID(),Double.NaN,0,0,0,1,"sbwdroneconfig:sk01",0,false));assertThrows(IllegalArgumentException.class,()->new Sk01Entry(UUID.randomUUID(),UUID.randomUUID(),0,0,0,0,0,"sbwdroneconfig:sk01",0,false));}
 @Test void packetsAreBoundedAndSourceIdentityRoundtrips(){var entry=entry(5);var p=new Sk01Packet(net.minecraft.resources.ResourceLocation.tryParse("minecraft:overworld"),entry.chunk(),22,true,false,List.of(new Sk01Packet.Change(entry.id(),entry)));var buf=new net.minecraft.network.FriendlyByteBuf(io.netty.buffer.Unpooled.buffer());try{Sk01Packet.encode(p,buf);assertEquals(p,Sk01Packet.decode(buf));}finally{buf.release();}assertThrows(IllegalArgumentException.class,()->new Sk01Packet(p.dimension(),p.chunk(),0,false,false,Collections.nCopies(65,p.changes().get(0))));}
}
